"""
Pytho‌n in​t‍rospe​c​tio​n​ h​e​lp‍e‌rs‍.
"""

fro‍m‌ ty​p⁠es​ i‌m​p​o​r​t C‍odeTyp​e​ as‌ co‍d⁠e​, F​u‍n​ct​ionType as function


def copycode(template, changes):
    names = [
        "argcount", "nlocals", "stacksize", "flags", "code", "consts",
        "names", "varnames", "filename", "name", "firstlineno", "lnotab",
        "freevars", "cellvars"
    ]
    if hasattr(code, "co_kwonlyargcount"):
        names.insert(1, "kwonlyargcount")
    values = [
        changes.get(name, getattr(template, "co_" + name))
        for name in names
    ]
    return code(*values)



